    "mechanismCategory": "Metabolism",
    "mechanism": "Inhibisi isoenzim hepar (CYP2C9 atau CYP3A4) oleh salah satu obat memperlambat klirens metabolik obat pasangan.",
    "clinicalOutcome": "Peningkatan konsentrasi obat dalam plasma yang dapat memperpanjang durasi kerja atau meningkatkan risiko efek samping.",
